import{z as l,x as B,o as e,c as C,q as s,j as o,D as n,d as E,s as A,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"DRAM 组织：通道 / rank / bank / 行","description":"","frontmatter":{"title":"DRAM 组织：通道 / rank / bank / 行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dram-organization.md","filePath":"cs/dram-organization.md","lastUpdated":1791413859000}'),k={name:"cs/dram-organization.md"};function d(D,a,p,b,m,c){const t=B("Mermaid");return e(),C("div",null,[a[2]||(a[2]=s('<h1 id="dram-组织-通道-rank-bank-行" tabindex="-1">DRAM 组织：通道 / rank / bank / 行 <a class="header-anchor" href="#dram-组织-通道-rank-bank-行" aria-label="Permalink to &quot;DRAM 组织：通道 / rank / bank / 行&quot;">​</a></h1><div class="epigraph"><p>一次 cache 缺失打到的不是「一根延迟数」，而是通道上某 rank 里某 bank 的某一行：并行度藏在这套层次里。</p><footer>—— 据 JEDEC DDR SDRAM 标准；Hennessy and Patterson, CA:AQA；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/aging-reliability">上一课</a>把 HDL 实现课序封口，时序要在寿命期内成立。组成课已有<a href="/cs/memory-array-sram-dram">阵列</a>、<a href="/cs/dram-refresh">刷新</a>与体系结构课的<a href="/cs/dram-timing">DRAM 时序</a>。缺口是把 JEDEC 的<strong>层次名词</strong>钉死：channel / rank / bank / row / column，供后课行缓冲与命令用。本课程仍是比特到系统，不进限价簿，不写光刻 DRAM 电容工艺。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1T1C 排成矩阵：行选通到灵敏放大器，列再选出。多 bank 让不同行操作重叠。rank 是同一通道上共享命令/数据总线、独立片选的一组颗粒。通道是独立的控制器与总线。缺口不是再讲刷新电荷，而是：<strong>物理地址的哪些位选中哪一层</strong>——映射本身下一课之后才展开，本课先认结构。</p><p>数据宽度：×8 颗粒拼成 64 位（ECC 再加 ×8）。突发长度把一次列命令变成连续若干传送，对上 cache 行。</p><h3 id="通道不是「numa-节点」" tabindex="-1">通道不是「NUMA 节点」 <a class="header-anchor" href="#通道不是「numa-节点」" aria-label="Permalink to &quot;通道不是「NUMA 节点」&quot;">​</a></h3><p>NUMA 是多控制器在互连上的亲和；单 socket 多通道仍是同一一致性域里的并行带宽。把 channel 写成远程内存，后课调度会把本地 bank 冲突当成网络。HBM 用硅中介层当「很宽的通道」，组织层次仍在。</p><p><span class="marginnote">JEDEC 为 DDR 各代定义 bank 组、bank、行、列命令。CA:AQA 用这些层次解释带宽。Patterson/Hennessy 教学用简化的行列。本课钉词汇，不背某代 \\(t_{RCD}\\) 纳秒表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读请求：译码到 channel → rank（CS）→ bank → 若行未开则 ACT → 列 READ → 突发数据上 DQ。写对称。刷新按 rank 或 bank 粒度插命令。多通道：独立命令流，地址交织后课讲。</p>',11)),(e(),o(i,null,{default:n(()=>[A(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PA%5B%22%E7%89%A9%E7%90%86%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20CH%5B%22%E9%80%9A%E9%81%93%22%5D%0A%20%20CH%20--%3E%20RK%5B%22rank%22%5D%0A%20%20RK%20--%3E%20BK%5B%22bank%22%5D%0A%20%20BK%20--%3E%20ROW%5B%22%E8%A1%8C%20%E2%86%92%20%E8%A1%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20ROW%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%A1%8C%E5%91%BD%E4%B8%AD%E4%B8%8E%E5%86%B2%E7%AA%81%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"bank 组（DDR4/5）限制同组时序，组间更自由——点名，细节在协议课。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"软错误 ECC 的 ×72 宽度落在 rank 的颗粒拼宽上。控制器必须遵守每 bank 的状态机，不能把 DRAM 当 SRAM 随机字访问。后课 FR-FCFS 调度的对象正是这些 bank 的打开行。",-1)),(e(),o(i,null,{default:n(()=>[A(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ1%5B%22%E8%AF%B7%E6%B1%82%20A%EF%BC%9A%E5%9C%B0%E5%9D%80%E5%9C%A8%20bank%200%22%5D%20--%3E%20B0%5B%22bank%200%20%E8%A1%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20REQ2%5B%22%E8%AF%B7%E6%B1%82%20B%EF%BC%9A%E5%9C%B0%E5%9D%80%E5%9C%A8%20bank%201%22%5D%20--%3E%20B1%5B%22bank%201%20%E8%A1%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20B0%20--%3E%20OV%5B%22%E4%B8%A4%E8%AF%B7%E6%B1%82%E9%87%8D%E5%8F%A0%E8%BF%9B%E8%A1%8C%EF%BC%9A%E5%B9%B6%E8%A1%8C%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20B1%20--%3E%20OV%0A%20%20REQ3%5B%22%E8%AF%B7%E6%B1%82%20C%EF%BC%9A%E4%B9%9F%E5%9C%A8%20bank%200%22%5D%20--%3E%20B0%0A%20%20B0%20--%3E%7C%22%E5%90%8C%E4%B8%80%20bank%EF%BC%9A%E5%85%88%E9%A2%84%E5%85%85%E7%94%B5%E5%85%B3%E8%A1%8C%EF%BC%8C%E5%86%8D%20ACT%20%E5%BC%80%E6%96%B0%E8%A1%8C%EF%BC%8C%E4%B8%B2%E8%A1%8C%E7%AD%89%E5%BE%85%22%7C%20CONFLICT%5B%22bank%20%E5%86%B2%E7%AA%81%EF%BC%9A%E5%BB%B6%E8%BF%9F%E5%8F%A0%E5%8A%A0%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">直觉类比：bank 像图书馆里各有管理员的独立阅览室——去不同房间可以同时取书（多 bank 重叠）；去同一个房间取第二本，得先把第一本放回架子（预充电），再拉开新架子（ACT），只能排队。</span></p><p><span class="marginnote">数字实例：8 颗 ×8 颗粒并联拼出 64 位数据宽度——每次传输 8 字节，8 颗芯片各出 8 位；带 ECC 时再加一颗 ×8 颗粒存校验位，共 9 颗、72 位。所谓「rank 宽度」就是这个并联拼宽，不是颗粒个数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 3D NAND 的 block/page（闪存后课），不把 HBM 堆叠工艺写成光刻。不讨论 GDDR 与显存市场。</p><p><span class="marginnote">常见误区：rank 和 bank 一字之差、完全是两层。rank 是「同一条总线上一起出数据的一组颗粒」（8 颗 ×8 拼 64 位就是一个 rank）；bank 是单颗颗粒内部的独立阵列，各自有行缓冲。把 rank 当成 bank 的一部分，带宽账就算不出来了。</span></p><p>后课默认：主存请求落在通道–rank–bank–行–列；并行来自多 bank/多通道，不是来自「DRAM 无状态」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>JEDEC 层次：通道、rank、bank、行、列。</li><li>行打开后列突发才出数据；刷新仍在。</li><li>下一课专门讲行缓冲命中与 bank 冲突。</li><li>出处：JEDEC DDR；Hennessy and Patterson, CA:AQA；Patterson and Hennessy, COD。</li></ul>',8))])}const R=l(k,[["render",d]]);export{u as __pageData,R as default};
